(() => {
  const $=s=>document.querySelector(s),client=window.haptosClient,form=$('#quote-form'),{currency,totals,validate}=HaptosQuote;
  let items=[],id=null,user=null,busy=false,dirty=false,pdfUrl=null,revision=0,history=[],offset=0,photosBusy=0;
  const message=t=>{$('#status').textContent=t;};
  const field=n=>form.elements.namedItem(n);
  const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
  const number=()=> 'H3D-'+today().replace(/-/g,'')+'-'+crypto.randomUUID().slice(0,6).toUpperCase();
  function markDirty(){dirty=true;$('#save-state').textContent='Alterações ainda não salvas.';if(pdfUrl){URL.revokeObjectURL(pdfUrl);pdfUrl=null;$('#pdf-preview').src='about:blank';}}
  function quote(){const q={items:items.map(i=>({...i})),version:1};for(const e of form.elements)if(e.name)q[e.name]=e.value;for(const k of ['discount','freight','setup','deposit'])q[k]=Number(q[k]);return q;}
  function summary(){const t=totals(quote());for(const [sel,key]of[['subtotal','subtotal'],['discount-total','discount'],['extras-total','extras'],['total','total'],['deposit-total','deposit'],['balance-total','balance']])$('#'+sel).textContent=currency(t[key]);$('.payment-summary').classList.toggle('has-deposit',t.deposit>0);items.forEach((item,i)=>{const el=document.querySelector('[data-total="'+i+'"]');if(el)el.textContent=(item.priceMode==='fixed'?'Total fechado do lote (não multiplica a quantidade): ':'Total do produto: ')+currency(t.lines[i]);});}
  function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;}
  function renderItems(){
    $('#items').replaceChildren();items.forEach((item,index)=>{
      const card=element('article','item'),heading=element('div','item-heading');heading.append(element('h3',null,'Produto '+(index+1)));const remove=element('button','text-button','Remover');remove.type='button';remove.disabled=items.length===1;remove.addEventListener('click',()=>{if(busy||photosBusy)return;items.splice(index,1);markDirty();renderItems();});heading.append(remove);card.append(heading);
      const grid=element('div','item-grid'),photo=element('div','photo-box');if(item.photo){const img=element('img');img.src=item.photo;img.alt='Prévia de '+(item.name||'produto');photo.append(img);const clear=element('button','text-button','Remover foto');clear.type='button';clear.addEventListener('click',()=>{if(busy||photosBusy)return;item.photo='';markDirty();renderItems();});photo.append(clear);}else photo.append(element('span',null,'Foto de como vai ficar'));
      const upload=element('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.setAttribute('aria-label','Foto do produto '+(index+1));upload.addEventListener('change',async()=>{const file=upload.files[0];if(!file||busy)return;photosBusy++;upload.disabled=true;message('Preparando imagem…');try{item.photo=await optimize(file);markDirty();renderItems();message('Foto adicionada.');}catch(e){message(e.message);}finally{photosBusy--;upload.disabled=false;}});photo.append(upload,element('span',null,'JPG, PNG ou WebP • até 10 MB'));grid.append(photo);
      const details=element('div','item-details');for(const [key,label,type,cls]of[['name','Produto','text',''],['quantity','Qtd.','number',''],['price',item.priceMode==='fixed'?'Valor fechado (R$)':'Preço un. (R$)','number',''],['description','Descrição / material / cores','textarea','full']]){
        const l=element('label',cls,label),e=element(type==='textarea'?'textarea':'input');if(type!=='textarea')e.type=type;e.value=item[key];e.required=key!=='description';if(type==='number'){e.min=key==='quantity'?'1':'0';e.max=key==='quantity'?'1000000':'10000000';e.step=key==='quantity'?'1':'0.01';}else e.maxLength=key==='name'?150:700;
        e.addEventListener('input',()=>{item[key]=type==='number'?(e.value===''?'':Number(e.value)):e.value;markDirty();summary();});if(key==='price'){
          const mode=element('select','price-mode');mode.setAttribute('aria-label','Tipo de preço do produto '+(index+1));
          for(const [value,title]of [['unit','Por unidade'],['fixed','Valor fechado']]){const option=element('option',null,title);option.value=value;mode.append(option);}mode.value=item.priceMode||'unit';
          mode.addEventListener('change',()=>{if(busy)return;item.priceMode=mode.value;markDirty();renderItems();});l.append(mode);
        }l.append(e);if(key==='description'){const extra=element('details','item-description');extra.open=!!item.description;extra.append(element('summary',null,'Descrição e personalização'),l);details.append(extra);}else details.append(l);
      }grid.append(details);card.append(grid);const total=element('p','item-total');total.dataset.total=index;card.append(total);$('#items').append(card);
    });$('#add-item').disabled=items.length>=20;summary();
  }
  async function optimize(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Use JPG, PNG ou WebP de até 10 MB.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('Use uma imagem de até 40 megapixels.');}const scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.78);if(data.length>250000)throw Error('Esta imagem ficou muito grande. Escolha uma foto mais simples.');return data;}
  function reset(q=null,keepId=false){if(!keepId)id=null;form.reset();for(const e of form.elements)if(e.name&&q&&q[e.name]!=null)e.value=q[e.name];if(!q){field('number').value=number();field('date').value=today();const valid=new Date(today()+'T12:00:00');valid.setDate(valid.getDate()+7);field('validity').value=valid.toLocaleDateString('en-CA');}items=q?.items.map(i=>({...i}))||[{name:'',description:'',quantity:1,price:0,photo:''}];dirty=false;renderItems();$('#save-state').textContent=keepId?'Orçamento salvo.':'Proposta nova. Salve para manter no histórico.';if(pdfUrl){URL.revokeObjectURL(pdfUrl);pdfUrl=null;}$('#pdf-preview').src='about:blank';}
  function guardedReset(){return !dirty||confirm('Há alterações não salvas. Deseja continuar sem salvar?');}
  function setBusy(value){busy=value;$('#quote-fields').disabled=value;for(const s of ['#generate','#save','#duplicate','#new-quote'])$(s).disabled=value;}
  async function authorized(){const {data,error}=await client.auth.getUser();if(error||!data.user)throw Error('Sua sessão expirou. Entre novamente.');const result=await client.from('haptos_portfolio_admins').select('user_id').eq('user_id',data.user.id).maybeSingle();if(result.error||!result.data)throw Error('Esta conta não tem acesso aos orçamentos.');return data.user;}
  async function save(q){const record={number:q.number,customer:q.customer,total:totals(q).total,payload:q,updated_at:new Date().toISOString()};const query=id?client.from('haptos_quotes').update(record).eq('id',id):client.from('haptos_quotes').insert(record);const {data,error}=await query.select('id').single();if(error||!data)throw Error('Não foi possível salvar. Confira sua conexão e tente novamente.');id=data.id;dirty=false;$('#save-state').textContent='Salvo no histórico da Haptos.';}
  function renderHistory(){const query=$('#history-search').value.toLowerCase();$('#history-list').replaceChildren();const filtered=history.filter(r=>(r.customer+' '+r.number).toLowerCase().includes(query));if(!filtered.length)$('#history-list').append(element('p','muted small',query?'Nenhum resultado nesta lista. Carregue mais para buscar propostas antigas.':'Nenhum orçamento salvo ainda.'));for(const row of filtered){const b=element('button','history-entry');b.type='button';b.append(element('strong',null,row.customer),element('span',null,row.number+' • '+currency(row.total)),element('span',null,new Date(row.updated_at).toLocaleDateString('pt-BR')));b.addEventListener('click',async()=>{if(busy||!guardedReset())return;setBusy(true);try{await authorized();const {data,error}=await client.from('haptos_quotes').select('id,payload').eq('id',row.id).single();if(error)throw error;id=data.id;reset(data.payload,true);$("#history-dialog").close();message('Orçamento carregado.');window.scrollTo({top:0,behavior:'smooth'});}catch{message('Não foi possível abrir este orçamento.');}finally{setBusy(false);}});$('#history-list').append(b);}}
  async function loadHistory(more=false){const current=revision;const start=more?offset:0;const {data,error}=await client.from('haptos_quotes').select('id,number,customer,total,updated_at').order('updated_at',{ascending:false}).order('id').range(start,start+20);if(current!==revision||!user)return;if(error)throw error;history=more?[...history,...data.slice(0,20)]:data.slice(0,20);offset=start+Math.min(data.length,20);$('#more-history').hidden=data.length<=20;renderHistory();}
  async function sessionChanged(session){if(session&&user?.id===session.user.id)return;const current=++revision;$('#dashboard').hidden=true;$('#logout').hidden=true;$('#login-panel').hidden=!!session;user=null;history=[];$('#history-list').replaceChildren();if(!session){reset();return;}try{const verified=await authorized();if(current!==revision)return;user=verified;$('#dashboard').hidden=false;$('#logout').hidden=false;reset();await loadHistory();message('');}catch(e){if(current!==revision)return;$('#login-panel').hidden=false;message(e.message||'Não foi possível verificar seu acesso.');}}
  if(!client){message('Não foi possível carregar a autenticação. Atualize a página.');$('#login-form button').disabled=true;return;}
  client.auth.onAuthStateChange((event,session)=>{if(['INITIAL_SESSION','SIGNED_IN','SIGNED_OUT'].includes(event))setTimeout(()=>sessionChanged(session),0);});
  $('#login-form').addEventListener('submit',async e=>{e.preventDefault();e.submitter.disabled=true;try{if($('#username').value.trim().toLowerCase()!=='haptos3d')throw Error();const {error}=await client.auth.signInWithPassword({email:HAPTOS_CONFIG.loginEmail,password:$('#password').value});if(error)throw error;$('#password').value='';message('');}catch{message('Usuário ou senha inválidos, ou acesso temporariamente indisponível.');}finally{e.submitter.disabled=false;}});
  $('#logout').addEventListener('click',async()=>{if(busy||!guardedReset())return;const {error}=await client.auth.signOut();if(error)message('Não foi possível sair. Tente novamente.');else message('Você saiu da área de orçamentos.');});
  $('#add-item').addEventListener('click',()=>{if(busy||photosBusy||items.length>=20)return;items.push({name:'',description:'',quantity:1,price:0,photo:''});markDirty();renderItems();});
  form.addEventListener('input',e=>{if(e.target.name){markDirty();summary();}});
  $('#new-quote').addEventListener('click',()=>{if(!photosBusy&&guardedReset()){reset();message('Novo orçamento.');}});
  $('#duplicate').addEventListener('click',()=>{if(photosBusy)return;const q=quote();q.number=number();q.date=today();reset(q);markDirty();message('Cópia criada. Salve para adicionar ao histórico.');});
  async function submit(generate){if(busy)return;if(photosBusy){message('Aguarde o processamento das fotos.');return;}if(!form.reportValidity())return;setBusy(true);message(generate?'Gerando PDF…':'Salvando…');try{await authorized();const q=validate(quote());if(!generate){await save(q);await loadHistory();message('Orçamento salvo.');return;}const bytes=await generateHaptosPDF(q);if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));$('#pdf-preview').src=pdfUrl;$('#download-pdf').href=pdfUrl;$('#download-pdf').download='Haptos3D_Orcamento_'+q.number.replace(/[^a-zA-Z0-9_-]/g,'_')+'.pdf';$('#pdf-dialog').showModal();message('PDF gerado. Você pode baixar e salvar a proposta no histórico.');}catch(e){message(e.message||'Não foi possível concluir. Tente novamente.');}finally{setBusy(false);}}
  form.addEventListener('submit',e=>{e.preventDefault();submit(true);});$('#save').addEventListener('click',()=>submit(false));$('#close-pdf').addEventListener('click',()=>$('#pdf-dialog').close());$('#refresh-history').addEventListener('click',()=>loadHistory().catch(()=>message('Não foi possível atualizar o histórico.')));$('#more-history').addEventListener('click',()=>loadHistory(true).catch(()=>message('Não foi possível carregar mais orçamentos.')));$('#history-search').addEventListener('input',renderHistory);
  $('#show-history').addEventListener('click',()=>$('#history-dialog').showModal());$('#close-history').addEventListener('click',()=>$('#history-dialog').close());
  form.addEventListener('invalid',e=>{let parent=e.target.parentElement;while(parent&&parent!==form){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}},true);
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
})();
